(** ** The lap *)

Lemma lap_0RB1LD_1LA1RC_1LA1RB_1LA0LA : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
