  - destruct (lapi_0RB1LD_1LA1RC_1LA1RB_1LA0LA p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_0RB1LD_1LA1RC_1LA1RB_1LA0LA B0_0RB1LD_1LA1RC_1LA1RB_1LA0LA B1_0RB1LD_1LA1RC_1LA1RB_1LA0LA 4 21 p j' [] []).
    + exact run_ovf_0RB1LD_1LA1RC_1LA1RB_1LA0LA.
    + reflexivity.
    + reflexivity.
    + exact (gso_0RB1LD_1LA1RC_1LA1RB_1LA0LA p j' E).
    + exact (geo_0RB1LD_1LA1RC_1LA1RB_1LA0LA p j' E).
    + lia.
