    apply (fire_via_ovf_lift tm Cc lapil_0RB1LD_1LA1RC_1LD1RB_0LA0RA (StC, S0)).
    intros p1 j1 E1.
    exact (firex_0RB1LD_1LA1RC_1LD1RB_0LA0RA [SWinR 4; SCycL 2 0; SWin 2; SWinL 1] (StC, S0) ltac:(vm_compute; reflexivity)
