  rewrite (gsi_0RB1LD_1LA1RC_1LD1RB____0LA p j q0 E).
  exact (srun_sound tm false true chi_0RB1LD_1LA1RC_1LD1RB____0LA A0_0RB1LD_1LA1RC_1LD1RB____0LA A1_0RB1LD_1LA1RC_1LD1RB____0LA 4 8
           run_int_0RB1LD_1LA1RC_1LD1RB____0LA (Ip q0 ++ [S0]) [] j
           ltac:(discriminate) ltac:(reflexivity)).
Qed.

Lemma gso_0RB1LD_1LA1RC_1LD1RB____0LA : forall p j, cview p = (S j, None) ->
