Lemma geo_0RB1LD_1LA1RC_1LD1RB____0LA : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_0RB1LD_1LA1RC_1LD1RB____0LA) = lift (Cc (Pos.succ p)).
