Definition mk_0RB1LD_1LA1RC_1RB0LA_0RD1LA (w : Sym) (d : Dir) (n : St) : option Trans := Some (mkTrans w d n).
Local Notation mk := mk_0RB1LD_1LA1RC_1RB0LA_0RD1LA.

(** 0RB1LD_1LA1RC_1RB0LA_0RD1LA *)
(** 0RB1LD_1LA1RC_1RB0LA_0RD1LA -- the real machine (its counter grows RIGHT). *)
Definition tm_0RB1LD_1LA1RC_1RB0LA_0RD1LA : TM := fun q s => match q, s with
  | StA, S0 => mk S0 DR StB | StA, S1 => mk S1 DL StD
  | StB, S0 => mk S1 DL StA | StB, S1 => mk S1 DR StC
  | StC, S0 => mk S1 DR StB | StC, S1 => mk S0 DL StA
  | StD, S0 => mk S0 DR StD | StD, S1 => mk S1 DL StA end.

(** Its mirror 0LB1RD_1RA1LC_1LB0RA_0LD1RA: the same counter grown leftward.  Every
    lemma below runs on the MIRRORED table;
    [Mirror.mirror_never_qh] transfers the conclusion back. *)
Definition tmm_0RB1LD_1LA1RC_1RB0LA_0RD1LA : TM := fun q s => match q, s with
  | StA, S0 => mk S0 DL StB | StA, S1 => mk S1 DR StD
  | StB, S0 => mk S1 DR StA | StB, S1 => mk S1 DL StC
  | StC, S0 => mk S1 DL StB | StC, S1 => mk S0 DR StA
  | StD, S0 => mk S0 DL StD | StD, S1 => mk S1 DR StA end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_0RB1LD_1LA1RC_1RB0LA_0RD1LA : list Instr := [].
Definition tmw_0RB1LD_1LA1RC_1RB0LA_0RD1LA : TM := tm_wrap_trs tmm_0RB1LD_1LA1RC_1RB0LA_0RD1LA pins_0RB1LD_1LA1RC_1RB0LA_0RD1LA.
Local Notation tm := tmw_0RB1LD_1LA1RC_1RB0LA_0RD1LA.

Lemma mirror_ok_0RB1LD_1LA1RC_1RB0LA_0RD1LA : mirror_tm tm_0RB1LD_1LA1RC_1RB0LA_0RD1LA = tmm_0RB1LD_1LA1RC_1RB0LA_0RD1LA.
Proof.
  apply functional_extensionality; intro q;
    apply functional_extensionality; intro b; destruct q, b; reflexivity.
Qed.

