Definition A0_0RB1LD_1LC0RC_1LA1RC_0RD0LA : sconf := mkC StC (mkS [] [S1;S1] 1 0 [S1;S0]) S0 (mkS [] [] 0 0 []).
Definition A1_0RB1LD_1LC0RC_1LA1RC_0RD0LA : sconf := mkC StC (mkS [] [S1;S0] 1 0 [S1;S1]) S0 (mkS [S0] [] 0 0 []).
Definition chi_0RB1LD_1LC0RC_1LA1RC_0RD0LA : list lstep := [SWinR 2; SRotL 1; SWin 1; SCycL 2 0; SWin 2; SCycR 2; SWin 5; SUnrotL 1].

Lemma run_int_0RB1LD_1LC0RC_1LA1RC_0RD0LA : srun tm false true chi_0RB1LD_1LC0RC_1LA1RC_0RD0LA A0_0RB1LD_1LC0RC_1LA1RC_0RD0LA = Some (A1_0RB1LD_1LC0RC_1LA1RC_0RD0LA, 4, 10).
Proof. vm_compute. reflexivity. Qed.

Definition B0_0RB1LD_1LC0RC_1LA1RC_0RD0LA : sconf := mkC StC (mkS [] [S1;S1] 1 0 [S1;S1;S0]) S0 (mkS [] [] 0 0 []).
Definition B1_0RB1LD_1LC0RC_1LA1RC_0RD0LA : sconf := mkC StC (mkS [] [S1;S0] 1 1 [S1;S1]) S0 (mkS [S0] [] 0 0 []).
(** ** The INNER anchor family -- Ip at StB *)
Definition Cin_0RB1LD_1LC0RC_1LA1RC_0RD0LA (v : positive) : cconf := (StB, (Ip v ++ [S1], S0, [])).
Local Notation Cin := Cin_0RB1LD_1LC0RC_1LA1RC_0RD0LA.

(** [E (2^n) = A^n C]: the value this family's count starts at. *)
Lemma epow2_0RB1LD_1LC0RC_1LA1RC_0RD0LA : forall n, Ip (pow2 n) = rep [S1;S0] n ++ [S1].
Proof. induction n; simpl; [reflexivity | rewrite IHn; reflexivity]. Qed.

(** Its own INTERIOR lap -- ordinary and affine.  Iterating it to the fill is
    where a [Theta(2^j)] lives, and [inner_to_fill_lift] keeps it inside an
    existential. *)
Definition AI0_0RB1LD_1LC0RC_1LA1RC_0RD0LA : sconf := mkC StB (mkS [] [S1;S1] 1 0 [S1;S0]) S0 (mkS [] [] 0 0 []).
Definition AI1_0RB1LD_1LC0RC_1LA1RC_0RD0LA : sconf := mkC StB (mkS [] [S1;S0] 1 0 [S1;S1]) S0 (mkS [S0;S0] [] 0 0 []).
Definition chn_0RB1LD_1LC0RC_1LA1RC_0RD0LA : list lstep := [SWinR 4; SCycL 2 0; SWin 4; SCycR 2; SWin 2].

Lemma run_inner_0RB1LD_1LC0RC_1LA1RC_0RD0LA : srun tm false true chn_0RB1LD_1LC0RC_1LA1RC_0RD0LA AI0_0RB1LD_1LC0RC_1LA1RC_0RD0LA = Some (AI1_0RB1LD_1LC0RC_1LA1RC_0RD0LA, 4, 10).
Proof. vm_compute. reflexivity. Qed.

(** *** boot: the outer overflow anchor -> the first inner anchor at [pow2 j] *)
Definition BB1_0RB1LD_1LC0RC_1LA1RC_0RD0LA : sconf := mkC StB (mkS [] [S1;S0] 1 0 [S1;S1]) S0 (mkS [S0;S0] [] 0 0 []).
Definition chb_0RB1LD_1LC0RC_1LA1RC_0RD0LA : list lstep := [SWinR 2; SRotL 1; SWin 1; SCycL 2 0; SWin 4; SCycR 2; SWin 2].

Lemma run_boot_0RB1LD_1LC0RC_1LA1RC_0RD0LA : srun tm true true chb_0RB1LD_1LC0RC_1LA1RC_0RD0LA B0_0RB1LD_1LC0RC_1LA1RC_0RD0LA = Some (BB1_0RB1LD_1LC0RC_1LA1RC_0RD0LA, 4, 9).
Proof. vm_compute. reflexivity. Qed.

(** *** exit: the last inner all-ones fill -> the outer successor *)
Definition BE0_0RB1LD_1LC0RC_1LA1RC_0RD0LA : sconf := mkC StB (mkS [] [S1;S1] 1 0 [S1;S1]) S0 (mkS [] [] 0 0 []).
Definition che_0RB1LD_1LC0RC_1LA1RC_0RD0LA : list lstep := [SWinR 4; SCycL 2 0; SWin 2; SWinL 4; SCycR 2; SWin 5; SRotL 1; SFoldL 1].

Lemma run_exit_0RB1LD_1LC0RC_1LA1RC_0RD0LA : srun tm true true che_0RB1LD_1LC0RC_1LA1RC_0RD0LA BE0_0RB1LD_1LC0RC_1LA1RC_0RD0LA = Some (B1_0RB1LD_1LC0RC_1LA1RC_0RD0LA, 4, 15).
Proof. vm_compute. reflexivity. Qed.

(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gsi_0RB1LD_1LC0RC_1LA1RC_0RD0LA : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] j A0_0RB1LD_1LC0RC_1LA1RC_0RD0LA.
Proof.
  intros p j q0 E. destruct (Alph_10_11_11.cview_some_Alph_10_11_11 p j q0 E) as (H1 & _).
  unfold Cc_0RB1LD_1LC0RC_1LA1RC_0RD0LA, cden, A0_0RB1LD_1LC0RC_1LA1RC_0RD0LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S1;S1] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

(** The lap ends on [S0] where the anchor has [] -- one trailing blank,
    which [lift] cannot see. *)
Lemma gei_0RB1LD_1LC0RC_1LA1RC_0RD0LA : forall p j q0, cview p = (j, Some q0) ->
  lift (cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] j A1_0RB1LD_1LC0RC_1LA1RC_0RD0LA) = lift (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct (Alph_10_11_11.cview_some_Alph_10_11_11 p j q0 E) as (_ & H2).
  unfold Cc_0RB1LD_1LC0RC_1LA1RC_0RD0LA, cden, A1_0RB1LD_1LC0RC_1LA1RC_0RD0LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  replace (0 * j + 0) with 0 by lia.
  cbn [rep app]. rewrite ?app_nil_r.
  change ([S0]) with (([]) ++ [S0]).
  rewrite !lift_app_blank.
  rewrite H2. first [ rewrite <- (app_assoc (rep [S1;S0] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapi_0RB1LD_1LC0RC_1LA1RC_0RD0LA : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof.
  intros p j q0 E.
  exists (4 * j + 10), (cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] j A1_0RB1LD_1LC0RC_1LA1RC_0RD0LA).
  split; [lia|]. split; [| exact (gei_0RB1LD_1LC0RC_1LA1RC_0RD0LA p j q0 E)].
  rewrite (gsi_0RB1LD_1LC0RC_1LA1RC_0RD0LA p j q0 E).
  exact (srun_sound tm false true chi_0RB1LD_1LC0RC_1LA1RC_0RD0LA A0_0RB1LD_1LC0RC_1LA1RC_0RD0LA A1_0RB1LD_1LC0RC_1LA1RC_0RD0LA 4 10
           run_int_0RB1LD_1LC0RC_1LA1RC_0RD0LA (Ap_Alph_10_11_11 q0 ++ [S0]) [] j
           ltac:(discriminate) ltac:(reflexivity)).
Qed.

Lemma gso_0RB1LD_1LC0RC_1LA1RC_0RD0LA : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_0RB1LD_1LC0RC_1LA1RC_0RD0LA.
Proof.
  intros p j E. destruct (Alph_10_11_11.cview_none_Alph_10_11_11 p j E) as (H1 & _).
  unfold Cc_0RB1LD_1LC0RC_1LA1RC_0RD0LA, cden, B0_0RB1LD_1LC0RC_1LA1RC_0RD0LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with (j) by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lbl_0RB1LD_1LC0RC_1LA1RC_0RD0LA : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_0RB1LD_1LC0RC_1LA1RC_0RD0LA : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_0RB1LD_1LC0RC_1LA1RC_0RD0LA) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (Alph_10_11_11.cview_none_Alph_10_11_11 p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_0RB1LD_1LC0RC_1LA1RC_0RD0LA
             = (StC, (rep [S1;S0] (S j) ++ [S1;S1], S0, ([]) ++ [S0]))).
  { unfold cden, B1_0RB1LD_1LC0RC_1LA1RC_0RD0LA, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (S j) by lia.
    replace (0 * j + 0) with 0 by lia.
    cbn [rep app]. first [ reflexivity
      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  assert (HC : Cc (Pos.succ p) = (StC, ((rep [S1;S0] (S j) ++ [S1;S1]) ++ [S0], S0, []))).
  { unfold Cc_0RB1LD_1LC0RC_1LA1RC_0RD0LA. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite !lift_app_blank. rewrite !lbl_0RB1LD_1LC0RC_1LA1RC_0RD0LA. reflexivity.
Qed.

Lemma gsn_0RB1LD_1LC0RC_1LA1RC_0RD0LA : forall v i q0, cview v = (i, Some q0) ->
  Cin v = cden (Ip q0 ++ [S1]) [] i AI0_0RB1LD_1LC0RC_1LA1RC_0RD0LA.
