Lemma lapin_0RB1LD_1LC0RC_1LA1RC_0RD0LA : forall v i q0, cview v = (i, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cin v) = Some c'
               /\ lift c' = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E.
  exists (4 * i + 10), (cden (Ip q0 ++ [S1]) [] i AI1_0RB1LD_1LC0RC_1LA1RC_0RD0LA).
  split; [lia|]. split; [| exact (gen_0RB1LD_1LC0RC_1LA1RC_0RD0LA v i q0 E)].
  rewrite (gsn_0RB1LD_1LC0RC_1LA1RC_0RD0LA v i q0 E).
  exact (srun_sound tm false true chn_0RB1LD_1LC0RC_1LA1RC_0RD0LA AI0_0RB1LD_1LC0RC_1LA1RC_0RD0LA AI1_0RB1LD_1LC0RC_1LA1RC_0RD0LA 4 10
           run_inner_0RB1LD_1LC0RC_1LA1RC_0RD0LA (Ip q0 ++ [S1]) [] i
           ltac:(discriminate) ltac:(reflexivity)).
