Lemma geo_0RB1LD_1LC1RB_0RB1LA_0LC0LC : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_0RB1LD_1LC1RB_0RB1LA_0LC0LC) = lift (Cc (Pos.succ p)).
