(** The outer OVERFLOW branch, composed.  The exponential cost is the
    [exists n] inside [inner_to_fill_lift]; no formula for it is ever
    written. *)
Lemma lapo_0RB1LD_1LC1RB_0RB1LA_0LC0LC : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin lapin_0RB1LD_1LC1RB_0RB1LA_0LC0LC p (pow2 j)).
  - exists (6 * j + 8), (cden [] [] j BB1_0RB1LD_1LC1RB_0RB1LA_0LC0LC).
    split; [lia|]. split; [| exact (gbo_0RB1LD_1LC1RB_0RB1LA_0LC0LC j)].
    rewrite (gso_0RB1LD_1LC1RB_0RB1LA_0LC0LC p j E).
    exact (srun_sound tm true true chb_0RB1LD_1LC1RB_0RB1LA_0LC0LC B0_0RB1LD_1LC1RB_0RB1LA_0LC0LC BB1_0RB1LD_1LC1RB_0RB1LA_0LC0LC 6 8
             run_boot_0RB1LD_1LC1RB_0RB1LA_0LC0LC [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (6 * j + 11), (cden [] [] j B1_0RB1LD_1LC1RB_0RB1LA_0LC0LC).
    split; [| exact (geo_0RB1LD_1LC1RB_0RB1LA_0LC0LC p j E)].
