(** The outer OVERFLOW branch, composed.  The exponential cost is the
    [exists n] inside [inner_to_fill_lift]; no formula for it is ever
    written. *)
Lemma lapo_0RB1LD_1LC1RB_0RB1LA_0RC0LC : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin2 lapin2_0RB1LD_1LC1RB_0RB1LA_0RC0LC p (pow2 j)).
  - assert (HB1 : exists n c, 0 < n /\ csteps tm n (Cc p) = Some c
                  /\ lift c = lift (Cin (pow2 j))).
    { exists (6 * j + 4), (cden [] [] j BB1_0RB1LD_1LC1RB_0RB1LA_0RC0LC).
      split; [lia|]. split; [| exact (gbo_0RB1LD_1LC1RB_0RB1LA_0RC0LC j)].
      rewrite (gso_0RB1LD_1LC1RB_0RB1LA_0RC0LC p j E).
      exact (srun_sound tm true true chb_0RB1LD_1LC1RB_0RB1LA_0RC0LC B0_0RB1LD_1LC1RB_0RB1LA_0RC0LC BB1_0RB1LD_1LC1RB_0RB1LA_0RC0LC 6 4
               run_boot_0RB1LD_1LC1RB_0RB1LA_0RC0LC [] [] j ltac:(reflexivity) ltac:(reflexivity)). }
    assert (HB2 : exists n c, 0 < n /\ csteps tm n (Cc p) = Some c
                  /\ lift c = lift (Cin2 (pow2 j))).
    { apply (boot_via_fill tm Cc Cin Cin2 lapin_0RB1LD_1LC1RB_0RB1LA_0RC0LC p (pow2 j) (pow2 j));
        [exact HB1|].
