  | StC, S0 => mk S0 DR StB | StC, S1 => mk S1 DL StA
  | StD, S0 => mk S1 DR StA | StD, S1 => mk S0 DL StC end.

(** Its mirror 0LB1RD_1RC1LB_0LB1RA_1LA0RC: the same counter grown leftward.  Every
    lemma below runs on the MIRRORED table;
    [Mirror.mirror_never_qh] transfers the conclusion back. *)
Definition tmm_0RB1LD_1LC1RB_0RB1LA_1RA0LC : TM := fun q s => match q, s with
  | StA, S0 => mk S0 DL StB | StA, S1 => mk S1 DR StD
  | StB, S0 => mk S1 DR StC | StB, S1 => mk S1 DL StB
  | StC, S0 => mk S0 DL StB | StC, S1 => mk S1 DR StA
  | StD, S0 => mk S1 DL StA | StD, S1 => mk S0 DR StC end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_0RB1LD_1LC1RB_0RB1LA_1RA0LC : list Instr := [].
Definition tmw_0RB1LD_1LC1RB_0RB1LA_1RA0LC : TM := tm_wrap_trs tmm_0RB1LD_1LC1RB_0RB1LA_1RA0LC pins_0RB1LD_1LC1RB_0RB1LA_1RA0LC.
Local Notation tm := tmw_0RB1LD_1LC1RB_0RB1LA_1RA0LC.

Lemma mirror_ok_0RB1LD_1LC1RB_0RB1LA_1RA0LC : mirror_tm tm_0RB1LD_1LC1RB_0RB1LA_1RA0LC = tmm_0RB1LD_1LC1RB_0RB1LA_1RA0LC.
Proof.
  apply functional_extensionality; intro q;
    apply functional_extensionality; intro b; destruct q, b; reflexivity.
Qed.

Definition Cc_0RB1LD_1LC1RB_0RB1LA_1RA0LC (p : positive) : cconf := (StC, (Ap_Alph_011_111_1 p ++ [S0], S0, [])).
Local Notation Cc := Cc_0RB1LD_1LC1RB_0RB1LA_1RA0LC.

(** ** The certificate *)

(** j = 0: the repeated block is absent, so the whole lap is concrete. *)
Definition Z0_0RB1LD_1LC1RB_0RB1LA_1RA0LC : sconf := mkC StC (mkS [S0;S1;S1] [] 0 0 []) S0 (mkS [] [] 0 0 []).
Definition Z1_0RB1LD_1LC1RB_0RB1LA_1RA0LC : sconf := mkC StC (mkS [S1;S1;S1] [] 0 0 []) S0 (mkS [] [] 0 0 []).
Definition chz_0RB1LD_1LC1RB_0RB1LA_1RA0LC : list lstep := [SWin 2].

Lemma run_z_0RB1LD_1LC1RB_0RB1LA_1RA0LC : srun tm false true chz_0RB1LD_1LC1RB_0RB1LA_1RA0LC Z0_0RB1LD_1LC1RB_0RB1LA_1RA0LC = Some (Z1_0RB1LD_1LC1RB_0RB1LA_1RA0LC, 0, 2).
Proof. vm_compute. reflexivity. Qed.

(** j = S j': one copy of the unit sits in the PREFIX, so the head always has
    a concrete cell to step onto. *)
Definition P0_0RB1LD_1LC1RB_0RB1LA_1RA0LC : sconf := mkC StC (mkS [S1;S1;S1] [S1;S1;S1] 1 0 [S0;S1;S1]) S0 (mkS [] [] 0 0 []).
Definition P1_0RB1LD_1LC1RB_0RB1LA_1RA0LC : sconf := mkC StC (mkS [S0;S1;S1] [S0;S1;S1] 1 0 [S1;S1;S1]) S0 (mkS [] [] 0 0 []).
Definition chp_0RB1LD_1LC1RB_0RB1LA_1RA0LC : list lstep := [SWin 3; SCycL 3 0; SWin 2; SCycR 3; SWin 3].

Lemma run_p_0RB1LD_1LC1RB_0RB1LA_1RA0LC : srun tm false true chp_0RB1LD_1LC1RB_0RB1LA_1RA0LC P0_0RB1LD_1LC1RB_0RB1LA_1RA0LC = Some (P1_0RB1LD_1LC1RB_0RB1LA_1RA0LC, 6, 8).
Proof. vm_compute. reflexivity. Qed.

Definition B0_0RB1LD_1LC1RB_0RB1LA_1RA0LC : sconf := mkC StC (mkS [] [S1;S1;S1] 1 0 [S1;S0]) S0 (mkS [] [] 0 0 []).
Definition B1_0RB1LD_1LC1RB_0RB1LA_1RA0LC : sconf := mkC StC (mkS [] [S0;S1;S1] 1 1 [S1]) S0 (mkS [] [] 0 0 []).
(** ** The INNER anchor family -- Ap_Alph_101_111_1 at StA *)
Definition Cin_0RB1LD_1LC1RB_0RB1LA_1RA0LC (v : positive) : cconf := (StA, (Ap_Alph_101_111_1 v ++ [S1], S0, [])).
Local Notation Cin := Cin_0RB1LD_1LC1RB_0RB1LA_1RA0LC.

(** [E (2^n) = A^n C]: the value this family's count starts at. *)
Lemma epow2_0RB1LD_1LC1RB_0RB1LA_1RA0LC : forall n, Ap_Alph_101_111_1 (pow2 n) = rep [S1;S0;S1] n ++ [S1].
Proof. induction n; simpl; [reflexivity | rewrite IHn; reflexivity]. Qed.

(** Its own INTERIOR lap -- ordinary and affine.  Iterating it to the fill is
    where a [Theta(2^j)] lives, and [inner_to_fill_lift] keeps it inside an
    existential. *)
Definition AI0_0RB1LD_1LC1RB_0RB1LA_1RA0LC : sconf := mkC StA (mkS [] [S1;S1;S1] 1 0 [S1;S0;S1]) S0 (mkS [] [] 0 0 []).
Definition AI1_0RB1LD_1LC1RB_0RB1LA_1RA0LC : sconf := mkC StA (mkS [] [S1;S0;S1] 1 0 [S1;S1;S1]) S0 (mkS [] [] 0 0 []).
Definition chn_0RB1LD_1LC1RB_0RB1LA_1RA0LC : list lstep := [SRotL 1; SWin 1; SCycL 3 0; SWin 2; SCycR 3; SWin 1; SUnrotL 1].

Lemma run_inner_0RB1LD_1LC1RB_0RB1LA_1RA0LC : srun tm false true chn_0RB1LD_1LC1RB_0RB1LA_1RA0LC AI0_0RB1LD_1LC1RB_0RB1LA_1RA0LC = Some (AI1_0RB1LD_1LC1RB_0RB1LA_1RA0LC, 6, 4).
Proof. vm_compute. reflexivity. Qed.

(** *** boot: the outer overflow anchor -> the first inner anchor at [pow2 j] *)
Definition BB1_0RB1LD_1LC1RB_0RB1LA_1RA0LC : sconf := mkC StA (mkS [] [S1;S0;S1] 1 0 [S1;S1]) S0 (mkS [] [] 0 0 []).
Definition chb_0RB1LD_1LC1RB_0RB1LA_1RA0LC : list lstep := [SRotL 1; SWin 1; SCycL 3 0; SWin 2; SCycR 3; SWin 1; SUnrotL 1].

Lemma run_boot_0RB1LD_1LC1RB_0RB1LA_1RA0LC : srun tm true true chb_0RB1LD_1LC1RB_0RB1LA_1RA0LC B0_0RB1LD_1LC1RB_0RB1LA_1RA0LC = Some (BB1_0RB1LD_1LC1RB_0RB1LA_1RA0LC, 6, 4).
Proof. vm_compute. reflexivity. Qed.

(** *** exit: the last inner all-ones fill -> the outer successor *)
Definition BE0_0RB1LD_1LC1RB_0RB1LA_1RA0LC : sconf := mkC StA (mkS [] [S1;S1;S1] 1 0 [S1;S1]) S0 (mkS [] [] 0 0 []).
Definition che_0RB1LD_1LC1RB_0RB1LA_1RA0LC : list lstep := [SRotL 1; SWin 1; SCycL 3 0; SWin 1; SWinL 3; SCycR 3; SWin 3; SWinR 1; SRotL 1; SFoldL 1].

Lemma run_exit_0RB1LD_1LC1RB_0RB1LA_1RA0LC : srun tm true true che_0RB1LD_1LC1RB_0RB1LA_1RA0LC BE0_0RB1LD_1LC1RB_0RB1LA_1RA0LC = Some (B1_0RB1LD_1LC1RB_0RB1LA_1RA0LC, 6, 9).
Proof. vm_compute. reflexivity. Qed.

(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gz_0RB1LD_1LC1RB_0RB1LA_1RA0LC : forall p q0, cview p = (0, Some q0) ->
  Cc p = cden (Ap_Alph_011_111_1 q0 ++ [S0]) [] 0 Z0_0RB1LD_1LC1RB_0RB1LA_1RA0LC /\
  cden (Ap_Alph_011_111_1 q0 ++ [S0]) [] 0 Z1_0RB1LD_1LC1RB_0RB1LA_1RA0LC = Cc (Pos.succ p).
Proof.
  intros p q0 E. destruct (Alph_011_111_1.cview_some_Alph_011_111_1 p 0 q0 E) as (H1 & H2).
  unfold Cc_0RB1LD_1LC1RB_0RB1LA_1RA0LC, cden, Z0_0RB1LD_1LC1RB_0RB1LA_1RA0LC, Z1_0RB1LD_1LC1RB_0RB1LA_1RA0LC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
  - rewrite H2; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gp_0RB1LD_1LC1RB_0RB1LA_1RA0LC : forall p j q0, cview p = (S j, Some q0) ->
  Cc p = cden (Ap_Alph_011_111_1 q0 ++ [S0]) [] j P0_0RB1LD_1LC1RB_0RB1LA_1RA0LC /\
  cden (Ap_Alph_011_111_1 q0 ++ [S0]) [] j P1_0RB1LD_1LC1RB_0RB1LA_1RA0LC = Cc (Pos.succ p).
Proof.
  intros p j q0 E. destruct (Alph_011_111_1.cview_some_Alph_011_111_1 p (S j) q0 E) as (H1 & H2).
  unfold Cc_0RB1LD_1LC1RB_0RB1LA_1RA0LC, cden, P0_0RB1LD_1LC1RB_0RB1LA_1RA0LC, P1_0RB1LD_1LC1RB_0RB1LA_1RA0LC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
  - rewrite H2; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapi_0RB1LD_1LC1RB_0RB1LA_1RA0LC : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct j as [|j'].
  - destruct (gz_0RB1LD_1LC1RB_0RB1LA_1RA0LC p q0 E) as (HA & HB).
    exists (0 * 0 + 2). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chz_0RB1LD_1LC1RB_0RB1LA_1RA0LC Z0_0RB1LD_1LC1RB_0RB1LA_1RA0LC Z1_0RB1LD_1LC1RB_0RB1LA_1RA0LC 0 2
               run_z_0RB1LD_1LC1RB_0RB1LA_1RA0LC (Ap_Alph_011_111_1 q0 ++ [S0]) [] 0
               ltac:(discriminate) ltac:(reflexivity)).
    f_equal. exact HB.
  - destruct (gp_0RB1LD_1LC1RB_0RB1LA_1RA0LC p j' q0 E) as (HA & HB).
    exists (6 * j' + 8). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chp_0RB1LD_1LC1RB_0RB1LA_1RA0LC P0_0RB1LD_1LC1RB_0RB1LA_1RA0LC P1_0RB1LD_1LC1RB_0RB1LA_1RA0LC 6 8
               run_p_0RB1LD_1LC1RB_0RB1LA_1RA0LC (Ap_Alph_011_111_1 q0 ++ [S0]) [] j'
               ltac:(discriminate) ltac:(reflexivity)).
    f_equal. exact HB.
Qed.

Lemma gso_0RB1LD_1LC1RB_0RB1LA_1RA0LC : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_0RB1LD_1LC1RB_0RB1LA_1RA0LC.
Proof.
  intros p j E. destruct (Alph_011_111_1.cview_none_Alph_011_111_1 p j E) as (H1 & _).
  unfold Cc_0RB1LD_1LC1RB_0RB1LA_1RA0LC, cden, B0_0RB1LD_1LC1RB_0RB1LA_1RA0LC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with (j) by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lbl_0RB1LD_1LC1RB_0RB1LA_1RA0LC : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_0RB1LD_1LC1RB_0RB1LA_1RA0LC : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_0RB1LD_1LC1RB_0RB1LA_1RA0LC) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (Alph_011_111_1.cview_none_Alph_011_111_1 p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_0RB1LD_1LC1RB_0RB1LA_1RA0LC
             = (StC, (rep [S0;S1;S1] (S j) ++ [S1], S0, []))).
  { unfold cden, B1_0RB1LD_1LC1RB_0RB1LA_1RA0LC, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (S j) by lia.
    replace (0 * j + 0) with 0 by lia.
    cbn [rep app]. first [ reflexivity
      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  assert (HC : Cc (Pos.succ p) = (StC, ((rep [S0;S1;S1] (S j) ++ [S1]) ++ [S0], S0, []))).
  { unfold Cc_0RB1LD_1LC1RB_0RB1LA_1RA0LC. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite !lbl_0RB1LD_1LC1RB_0RB1LA_1RA0LC. reflexivity.
Qed.

Lemma gsn_0RB1LD_1LC1RB_0RB1LA_1RA0LC : forall v i q0, cview v = (i, Some q0) ->
  Cin v = cden (Ap_Alph_101_111_1 q0 ++ [S1]) [] i AI0_0RB1LD_1LC1RB_0RB1LA_1RA0LC.
Proof.
  intros v i q0 E. destruct (Alph_101_111_1.cview_some_Alph_101_111_1 v i q0 E) as (H1 & _).
  unfold Cin_0RB1LD_1LC1RB_0RB1LA_1RA0LC, cden, AI0_0RB1LD_1LC1RB_0RB1LA_1RA0LC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * i + 0) with i by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S1;S1;S1] i)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gen_0RB1LD_1LC1RB_0RB1LA_1RA0LC : forall v i q0, cview v = (i, Some q0) ->
  lift (cden (Ap_Alph_101_111_1 q0 ++ [S1]) [] i AI1_0RB1LD_1LC1RB_0RB1LA_1RA0LC) = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E. destruct (Alph_101_111_1.cview_some_Alph_101_111_1 v i q0 E) as (_ & H2).
  unfold Cin_0RB1LD_1LC1RB_0RB1LA_1RA0LC, cden, AI1_0RB1LD_1LC1RB_0RB1LA_1RA0LC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * i + 0) with i by lia.
  replace (0 * i + 0) with 0 by lia.
  cbn [rep app]. rewrite ?app_nil_r.
  rewrite H2. first [ rewrite <- (app_assoc (rep [S1;S0;S1] i)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapin_0RB1LD_1LC1RB_0RB1LA_1RA0LC : forall v i q0, cview v = (i, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cin v) = Some c'
               /\ lift c' = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E.
  exists (6 * i + 4), (cden (Ap_Alph_101_111_1 q0 ++ [S1]) [] i AI1_0RB1LD_1LC1RB_0RB1LA_1RA0LC).
  split; [lia|]. split; [| exact (gen_0RB1LD_1LC1RB_0RB1LA_1RA0LC v i q0 E)].
  rewrite (gsn_0RB1LD_1LC1RB_0RB1LA_1RA0LC v i q0 E).
  exact (srun_sound tm false true chn_0RB1LD_1LC1RB_0RB1LA_1RA0LC AI0_0RB1LD_1LC1RB_0RB1LA_1RA0LC AI1_0RB1LD_1LC1RB_0RB1LA_1RA0LC 6 4
           run_inner_0RB1LD_1LC1RB_0RB1LA_1RA0LC (Ap_Alph_101_111_1 q0 ++ [S1]) [] i
           ltac:(discriminate) ltac:(reflexivity)).
Qed.

(** The chain into this family lands on its anchor up to 0/0
    trailing blanks. *)
Lemma gbo_0RB1LD_1LC1RB_0RB1LA_1RA0LC : forall j, lift (cden [] [] j BB1_0RB1LD_1LC1RB_0RB1LA_1RA0LC) = lift (Cin (pow2 j)).
Proof.
  intro j.
  assert (HD : cden [] [] j BB1_0RB1LD_1LC1RB_0RB1LA_1RA0LC = (StA, (rep [S1;S0;S1] j ++ [S1;S1], S0, []))).
  { unfold cden, BB1_0RB1LD_1LC1RB_0RB1LA_1RA0LC, sden;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 0) with j by lia.
    cbn [rep app]. rewrite <- ?app_assoc. cbn [app]. rewrite ?app_nil_r.
    reflexivity. }
  assert (HC : Cin (pow2 j) = (StA, (rep [S1;S0;S1] j ++ [S1;S1], S0, []))).
  { unfold Cin_0RB1LD_1LC1RB_0RB1LA_1RA0LC. rewrite epow2_0RB1LD_1LC1RB_0RB1LA_1RA0LC.
    first [ rewrite <- app_assoc; reflexivity
          | rewrite ?app_nil_r; reflexivity
          | cbn [app]; rewrite <- ?app_assoc; cbn [app];
            rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite ?lbl_0RB1LD_1LC1RB_0RB1LA_1RA0LC. rewrite ?lift_app_blank. reflexivity.
Qed.

(** This family's all-ones fill IS the next chain's start.  [cview (fill
    (pow2 j)) = (S j, None)] ([NestedLapLift.cview_fill_pow2]), so the
    family's own overflow decomposition names the word. *)
Lemma gxi_0RB1LD_1LC1RB_0RB1LA_1RA0LC : forall j, Cin (fill (pow2 j)) = cden [] [] j BE0_0RB1LD_1LC1RB_0RB1LA_1RA0LC.
Proof.
  intro j.
  destruct (Alph_101_111_1.cview_none_Alph_101_111_1 (fill (pow2 j)) j (cview_fill_pow2 j)) as (H1 & _).
  unfold Cin_0RB1LD_1LC1RB_0RB1LA_1RA0LC, cden, BE0_0RB1LD_1LC1RB_0RB1LA_1RA0LC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  replace (0 * j + 0) with 0 by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- ?app_assoc; cbn [app];
        rewrite ?app_nil_r; reflexivity | reflexivity ].
Qed.

(** The interior lap, restated up to [lift] -- what [vis_via_ovf_lift] and
    [vis_via_fill] consume. *)
Lemma lapil_0RB1LD_1LC1RB_0RB1LA_1RA0LC : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof. intros p j q0 E. destruct (lapi_0RB1LD_1LC1RB_0RB1LA_1RA0LC p j q0 E) as (n & Hn & Hr).
  exists n, (Cc (Pos.succ p)).
  split; [exact Hn | split; [exact Hr | reflexivity]]. Qed.

(** The outer OVERFLOW branch, composed.  The exponential cost is the
    [exists n] inside [inner_to_fill_lift]; no formula for it is ever
    written. *)
Lemma lapo_0RB1LD_1LC1RB_0RB1LA_1RA0LC : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin lapin_0RB1LD_1LC1RB_0RB1LA_1RA0LC p (pow2 j)).
  - exists (6 * j + 4), (cden [] [] j BB1_0RB1LD_1LC1RB_0RB1LA_1RA0LC).
    split; [lia|]. split; [| exact (gbo_0RB1LD_1LC1RB_0RB1LA_1RA0LC j)].
    rewrite (gso_0RB1LD_1LC1RB_0RB1LA_1RA0LC p j E).
    exact (srun_sound tm true true chb_0RB1LD_1LC1RB_0RB1LA_1RA0LC B0_0RB1LD_1LC1RB_0RB1LA_1RA0LC BB1_0RB1LD_1LC1RB_0RB1LA_1RA0LC 6 4
             run_boot_0RB1LD_1LC1RB_0RB1LA_1RA0LC [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (6 * j + 9), (cden [] [] j B1_0RB1LD_1LC1RB_0RB1LA_1RA0LC).
    split; [| exact (geo_0RB1LD_1LC1RB_0RB1LA_1RA0LC p j E)].
    rewrite (gxi_0RB1LD_1LC1RB_0RB1LA_1RA0LC j).
    exact (srun_sound tm true true che_0RB1LD_1LC1RB_0RB1LA_1RA0LC BE0_0RB1LD_1LC1RB_0RB1LA_1RA0LC B1_0RB1LD_1LC1RB_0RB1LA_1RA0LC 6 9
             run_exit_0RB1LD_1LC1RB_0RB1LA_1RA0LC [] [] j ltac:(reflexivity) ltac:(reflexivity)).
Qed.

(** A state firing in the EXIT chain is reached from the outer overflow
    anchor by boot + the inner counter's own laps + that prefix. *)
Lemma visx_0RB1LD_1LC1RB_0RB1LA_1RA0LC : forall (l : list lstep) (q : St),
  srun_st tm true true l BE0_0RB1LD_1LC1RB_0RB1LA_1RA0LC = Some q ->
  forall p j, cview p = (S j, None) ->
  exists k e, stepn tm k (lift (Cc p)) = Some e /\ fst e = q.
Proof.
  intros l q Hst p j E.
