Qed.

(** ** Bootstrap *)

Lemma boot_0RB1LD_1LC1RB_0RB1LA_1RA0LC : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 2.
  assert (H : match csteps tm 2 c0 with
