    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_0RB1LD_1LC1RB_0RB1LD_0RB0LA : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_0RB1LD_1LC1RB_0RB1LD_0RB0LA = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_0RB1LD_1LC1RB_0RB1LD_0RB0LA p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_0RB1LD_1LC1RB_0RB1LD_0RB0LA p j E)].
Qed.


(** An instruction firing in the EXIT chain is reached from the outer overflow
    anchor by boot + the inner counter's own laps + that prefix. *)
Lemma firex_0RB1LD_1LC1RB_0RB1LD_0RB0LA : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l BE0_0RB1LD_1LC1RB_0RB1LD_0RB0LA = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k e, stepn tm k (lift (Cc p)) = Some e /\ instr_of e = t.
Proof.
  intros l t Hst p j E.
  apply (fire_via_fill tm Cc Cin lapin_0RB1LD_1LC1RB_0RB1LD_0RB0LA t p (pow2 j)).
  - exists (4 * j + 7), (cden [] [] j BB1_0RB1LD_1LC1RB_0RB1LD_0RB0LA). split;
      [| exact (gbo_0RB1LD_1LC1RB_0RB1LD_0RB0LA j)].
    rewrite (gso_0RB1LD_1LC1RB_0RB1LD_0RB0LA p j E).
    exact (srun_sound tm true true chb_0RB1LD_1LC1RB_0RB1LD_0RB0LA B0_0RB1LD_1LC1RB_0RB1LD_0RB0LA BB1_0RB1LD_1LC1RB_0RB1LD_0RB0LA 4 7
             run_boot_0RB1LD_1LC1RB_0RB1LD_0RB0LA [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - apply (fire_lift_of_csteps tm (fun _ : positive => Cin (fill (pow2 j))) xH).
    apply (fire_of_run_instr tm (fun _ : positive => Cin (fill (pow2 j)))
                      true true l BE0_0RB1LD_1LC1RB_0RB1LD_0RB0LA xH j [] []);
      [exact Hst | reflexivity | reflexivity | exact (gxi_0RB1LD_1LC1RB_0RB1LD_0RB0LA j)].
Qed.

(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_0RB1LD_1LC1RB_0RB1LD_0RB0LA : forall t, ~ In t pins_0RB1LD_1LC1RB_0RB1LD_0RB0LA ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
