    apply (fire_via_ovf_lift tm Cc lapil_0RB1LD_1LC1RB_0RB1LD_0RB0LA (StA, S1)).
    intros p1 j1 E1.
    exact (firex_0RB1LD_1LC1RB_0RB1LD_0RB0LA [SWinR 2; SCycL 2 0; SWin 2; SWinL 4] (StA, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B0 *)
    apply (fire_via_ovf tm Cc Hi (StB, S0)), fireo_0RB1LD_1LC1RB_0RB1LD_0RB0LA
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 2]).
    vm_compute; reflexivity.
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_0RB1LD_1LC1RB_0RB1LD_0RB0LA
      with (l := [SRotL 1; SWin 1]).
    vm_compute; reflexivity.
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_0RB1LD_1LC1RB_0RB1LD_0RB0LA
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 4; SCycR 2; SWin 2; SWin 1]).
    vm_compute; reflexivity.
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_0RB1LD_1LC1RB_0RB1LD_0RB0LA
