(** 0RB1LD_1LC1RB_0RC1LA_0LB0LC -- the real machine (its counter grows RIGHT). *)
Definition tm_0RB1LD_1LC1RB_0RC1LA_0LB0LC : TM := fun q s => match q, s with
  | StA, S0 => mk S0 DR StB | StA, S1 => mk S1 DL StD
  | StB, S0 => mk S1 DL StC | StB, S1 => mk S1 DR StB
  | StC, S0 => mk S0 DR StC | StC, S1 => mk S1 DL StA
  | StD, S0 => mk S0 DL StB | StD, S1 => mk S0 DL StC end.

(** Its mirror 0LB1RD_1RC1LB_0LC1RA_0RB0RC: the same counter grown leftward.  Every
    lemma below runs on the MIRRORED table;
    [Mirror.mirror_never_qh] transfers the conclusion back. *)
Definition tmm_0RB1LD_1LC1RB_0RC1LA_0LB0LC : TM := fun q s => match q, s with
  | StA, S0 => mk S0 DL StB | StA, S1 => mk S1 DR StD
  | StB, S0 => mk S1 DR StC | StB, S1 => mk S1 DL StB
  | StC, S0 => mk S0 DL StC | StC, S1 => mk S1 DR StA
  | StD, S0 => mk S0 DR StB | StD, S1 => mk S0 DR StC end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_0RB1LD_1LC1RB_0RC1LA_0LB0LC : list Instr := [].
Definition tmw_0RB1LD_1LC1RB_0RC1LA_0LB0LC : TM := tm_wrap_trs tmm_0RB1LD_1LC1RB_0RC1LA_0LB0LC pins_0RB1LD_1LC1RB_0RC1LA_0LB0LC.
Local Notation tm := tmw_0RB1LD_1LC1RB_0RC1LA_0LB0LC.

Lemma mirror_ok_0RB1LD_1LC1RB_0RC1LA_0LB0LC : mirror_tm tm_0RB1LD_1LC1RB_0RC1LA_0LB0LC = tmm_0RB1LD_1LC1RB_0RC1LA_0LB0LC.
Proof.
  apply functional_extensionality; intro q;
    apply functional_extensionality; intro b; destruct q, b; reflexivity.
Qed.

