  unfold Cc_0RB1LD_1LC1RB_0RC1LA_0LB0LC, cden, A1_0RB1LD_1LC1RB_0RC1LA_0LB0LC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  rewrite H2. first [ rewrite <- (app_assoc (rep [S1;S0;S1] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapi_0RB1LD_1LC1RB_0RC1LA_0LB0LC : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. exists (6 * j + 4). split; [lia|].
  rewrite (gsi_0RB1LD_1LC1RB_0RC1LA_0LB0LC p j q0 E).
  rewrite (srun_sound tm false true chi_0RB1LD_1LC1RB_0RC1LA_0LB0LC A0_0RB1LD_1LC1RB_0RC1LA_0LB0LC A1_0RB1LD_1LC1RB_0RC1LA_0LB0LC 6 4
             run_int_0RB1LD_1LC1RB_0RC1LA_0LB0LC (Ap_Alph_101_111_1 q0 ++ [S0;S1;S1;S1;S0]) [] j
             ltac:(discriminate) ltac:(reflexivity)).
