Qed.

Lemma gso_0RB1LD_1LC1RB_0RC1LA_0LB0LC : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_0RB1LD_1LC1RB_0RC1LA_0LB0LC.
Proof.
  intros p j E. destruct (Alph_101_111_1.cview_none_Alph_101_111_1 p j E) as (H1 & _).
  unfold Cc_0RB1LD_1LC1RB_0RC1LA_0LB0LC, cden, B0_0RB1LD_1LC1RB_0RC1LA_0LB0LC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with (j) by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lbl_0RB1LD_1LC1RB_0RC1LA_0LB0LC : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_0RB1LD_1LC1RB_0RC1LA_0LB0LC : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_0RB1LD_1LC1RB_0RC1LA_0LB0LC) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (Alph_101_111_1.cview_none_Alph_101_111_1 p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_0RB1LD_1LC1RB_0RC1LA_0LB0LC
             = (StA, (rep [S1;S0;S1] (S j) ++ [S1;S0;S1;S1;S1], S0, []))).
  { unfold cden, B1_0RB1LD_1LC1RB_0RC1LA_0LB0LC, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (S j) by lia.
    replace (0 * j + 0) with 0 by lia.
    cbn [rep app]. first [ reflexivity
      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  assert (HC : Cc (Pos.succ p) = (StA, ((rep [S1;S0;S1] (S j) ++ [S1;S0;S1;S1;S1]) ++ [S0], S0, []))).
  { unfold Cc_0RB1LD_1LC1RB_0RC1LA_0LB0LC. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite !lbl_0RB1LD_1LC1RB_0RC1LA_0LB0LC. reflexivity.
Qed.

