  exact (srun_sound tm false true chn_0RB1LD_1LC1RB_0RC1LA_0LB0LC AI0_0RB1LD_1LC1RB_0RC1LA_0LB0LC AI1_0RB1LD_1LC1RB_0RC1LA_0LB0LC 6 4
           run_inner_0RB1LD_1LC1RB_0RC1LA_0LB0LC (Ap_Alph_101_111_11 q0 ++ [S1;S1;S1]) [] i
