(** The chain into this family lands on its anchor up to 1/0
    trailing blanks. *)
Lemma gbo_0RB1LD_1LC1RB_0RC1LA_0LB0LC : forall j, lift (cden [] [] j BB1_0RB1LD_1LC1RB_0RC1LA_0LB0LC) = lift (Cin (pow2 j)).
Proof.
  intro j.
  assert (HD : cden [] [] j BB1_0RB1LD_1LC1RB_0RC1LA_0LB0LC = (StA, ((rep [S1;S0;S1] j ++ [S1;S1;S1;S1;S1]) ++ [S0], S0, []))).
  { unfold cden, BB1_0RB1LD_1LC1RB_0RC1LA_0LB0LC, sden;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 0) with j by lia.
    cbn [rep app]. rewrite <- ?app_assoc. cbn [app]. rewrite ?app_nil_r.
    reflexivity. }
  assert (HC : Cin (pow2 j) = (StA, (rep [S1;S0;S1] j ++ [S1;S1;S1;S1;S1], S0, []))).
  { unfold Cin_0RB1LD_1LC1RB_0RC1LA_0LB0LC. rewrite epow2_0RB1LD_1LC1RB_0RC1LA_0LB0LC.
    first [ rewrite <- app_assoc; reflexivity
          | rewrite ?app_nil_r; reflexivity
          | cbn [app]; rewrite <- ?app_assoc; cbn [app];
            rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite ?lbl_0RB1LD_1LC1RB_0RC1LA_0LB0LC. rewrite ?lift_app_blank. reflexivity.
