Lemma gsi_0RB1LD_1LC1RB_0RC1LA_1LA0LC : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Ap_Alph_110_111_111 q0 ++ [S0]) [] j A0_0RB1LD_1LC1RB_0RC1LA_1LA0LC.
