Lemma fire_0RB1LD_1LC1RB_0RC1LA_1LC0LC : forall t, ~ In t pins_0RB1LD_1LC1RB_0RC1LA_1LC0LC ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
