  intro j.
  assert (HD : cden [] [] j BB1_0RB1LD_1LC1RB_1LA1LA_0LC0RA = (StA, ((rep [S1;S0;S1] j ++ [S1;S1;S1;S1;S1]) ++ [S0], S0, []))).
  { unfold cden, BB1_0RB1LD_1LC1RB_1LA1LA_0LC0RA, sden;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 0) with j by lia.
    cbn [rep app]. rewrite <- ?app_assoc. cbn [app]. rewrite ?app_nil_r.
    reflexivity. }
  assert (HC : Cin (pow2 j) = (StA, (rep [S1;S0;S1] j ++ [S1;S1;S1;S1;S1], S0, []))).
  { unfold Cin_0RB1LD_1LC1RB_1LA1LA_0LC0RA. rewrite epow2_0RB1LD_1LC1RB_1LA1LA_0LC0RA.
    first [ rewrite <- app_assoc; reflexivity
