(** This family's all-ones fill IS the next chain's start.  [cview (fill
    (pow2 j)) = (S j, None)] ([NestedLapLift.cview_fill_pow2]), so the
    family's own overflow decomposition names the word. *)
Lemma gxi_0RB1LD_1LC1RB_1LA1LA_0LC0RA : forall j, Cin (fill (pow2 j)) = cden [] [] j BE0_0RB1LD_1LC1RB_1LA1LA_0LC0RA.
Proof.
  intro j.
  destruct (Alph_101_111_11.cview_none_Alph_101_111_11 (fill (pow2 j)) j (cview_fill_pow2 j)) as (H1 & _).
  unfold Cin_0RB1LD_1LC1RB_1LA1LA_0LC0RA, cden, BE0_0RB1LD_1LC1RB_1LA1LA_0LC0RA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  replace (0 * j + 0) with 0 by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- ?app_assoc; cbn [app];
        rewrite ?app_nil_r; reflexivity | reflexivity ].
Qed.

(** The interior lap, restated up to [lift] -- what [vis_via_ovf_lift] and
    [vis_via_fill] consume. *)
Lemma lapil_0RB1LD_1LC1RB_1LA1LA_0LC0RA : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof. intros p j q0 E. destruct (lapi_0RB1LD_1LC1RB_1LA1LA_0LC0RA p j q0 E) as (n & Hn & Hr).
  exists n, (Cc (Pos.succ p)).
  split; [exact Hn | split; [exact Hr | reflexivity]]. Qed.

(** The outer OVERFLOW branch, composed.  The exponential cost is the
    [exists n] inside [inner_to_fill_lift]; no formula for it is ever
    written. *)
Lemma lapo_0RB1LD_1LC1RB_1LA1LA_0LC0RA : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin lapin_0RB1LD_1LC1RB_1LA1LA_0LC0RA p (pow2 j)).
  - exists (8 * j + 4), (cden [] [] j BB1_0RB1LD_1LC1RB_1LA1LA_0LC0RA).
    split; [lia|]. split; [| exact (gbo_0RB1LD_1LC1RB_1LA1LA_0LC0RA j)].
    rewrite (gso_0RB1LD_1LC1RB_1LA1LA_0LC0RA p j E).
    exact (srun_sound tm true true chb_0RB1LD_1LC1RB_1LA1LA_0LC0RA B0_0RB1LD_1LC1RB_1LA1LA_0LC0RA BB1_0RB1LD_1LC1RB_1LA1LA_0LC0RA 8 4
             run_boot_0RB1LD_1LC1RB_1LA1LA_0LC0RA [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (8 * j + 16), (cden [] [] j B1_0RB1LD_1LC1RB_1LA1LA_0LC0RA).
    split; [| exact (geo_0RB1LD_1LC1RB_1LA1LA_0LC0RA p j E)].
    rewrite (gxi_0RB1LD_1LC1RB_1LA1LA_0LC0RA j).
    exact (srun_sound tm true true che_0RB1LD_1LC1RB_1LA1LA_0LC0RA BE0_0RB1LD_1LC1RB_1LA1LA_0LC0RA B1_0RB1LD_1LC1RB_1LA1LA_0LC0RA 8 16
             run_exit_0RB1LD_1LC1RB_1LA1LA_0LC0RA [] [] j ltac:(reflexivity) ltac:(reflexivity)).
Qed.

(** A state firing in the EXIT chain is reached from the outer overflow
    anchor by boot + the inner counter's own laps + that prefix. *)
Lemma visx_0RB1LD_1LC1RB_1LA1LA_0LC0RA : forall (l : list lstep) (q : St),
  srun_st tm true true l BE0_0RB1LD_1LC1RB_1LA1LA_0LC0RA = Some q ->
  forall p j, cview p = (S j, None) ->
  exists k e, stepn tm k (lift (Cc p)) = Some e /\ fst e = q.
Proof.
  intros l q Hst p j E.
  apply (vis_via_fill tm Cc Cin lapin_0RB1LD_1LC1RB_1LA1LA_0LC0RA q p (pow2 j)).
  - exists (8 * j + 4), (cden [] [] j BB1_0RB1LD_1LC1RB_1LA1LA_0LC0RA). split;
      [| exact (gbo_0RB1LD_1LC1RB_1LA1LA_0LC0RA j)].
    rewrite (gso_0RB1LD_1LC1RB_1LA1LA_0LC0RA p j E).
    exact (srun_sound tm true true chb_0RB1LD_1LC1RB_1LA1LA_0LC0RA B0_0RB1LD_1LC1RB_1LA1LA_0LC0RA BB1_0RB1LD_1LC1RB_1LA1LA_0LC0RA 8 4
             run_boot_0RB1LD_1LC1RB_1LA1LA_0LC0RA [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - apply (vis_lift_of_csteps tm (fun _ : positive => Cin (fill (pow2 j))) xH).
    apply (vis_of_run tm (fun _ : positive => Cin (fill (pow2 j)))
                      true true l BE0_0RB1LD_1LC1RB_1LA1LA_0LC0RA xH j [] []);
      [exact Hst | reflexivity | reflexivity | exact (gxi_0RB1LD_1LC1RB_1LA1LA_0LC0RA j)].
